/* Rentie frontend demo. No network calls, backend, or real payments. */
(function(){
'use strict';
const R=window.Rentie,KEY='rentie-demo-v3',page=document.body.dataset.page,params=new URLSearchParams(location.search);
const $=(s,root=document)=>root.querySelector(s),$$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(n,cls='')=>`<i data-lucide="${n}" class="${cls}" aria-hidden="true"></i>`;
const V=v=>Math.round(v||0).toLocaleString('vi-VN')+'đ',unit=i=>i.unit==='hour'?'giờ':'ngày',mode=i=>i.mode==='counter'?'Nhận tại quầy':'Tự giao nhận';
const date=v=>v?new Intl.DateTimeFormat('vi-VN',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Bangkok'}).format(new Date(v)):'Chưa ghi nhận';
const stamp=(v=Date.now())=>new Intl.DateTimeFormat('sv-SE',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Bangkok'}).format(new Date(v)).replace(' ','T');
const toISO=v=>new Date(v+':00+07:00').toISOString();
const titles={home:'Khám phá',catalog:'Tìm vật phẩm',item:'Chi tiết vật phẩm',publish:'Đăng vật phẩm',dashboard:'Tổng quan',orders:'Đơn thuê',wallet:'Ví Rentie',inventory:'Đồ của tôi',warehouse:'Quầy ký gửi',admin:'Quản trị',disputes:'Khiếu nại',scan:'Quét mã giao nhận',account:'Tài khoản',guide:'Cách thuê đồ',sitemap:'Sơ đồ website'};
const statusNames={pending:'Chờ duyệt',approved:'Đang hiển thị',booked:'Chờ nhận đồ',active:'Đang thuê',returned:'Chờ tất toán',completed:'Hoàn tất',cancelled:'Đã hủy',disputed:'Đang khiếu nại',rejected:'Bị từ chối',hidden:'Đã ẩn',withdrawn:'Đã nhận lại',pickup:'Chờ chủ nhận',closed:'Đã đóng',open:'Chờ xử lý',resolved:'Đã giải quyết'};
const badge=(status,label)=>`<span class="tag ${esc(status)}">${esc(label||statusNames[status]||status)}</span>`;
let db;try{db=JSON.parse(localStorage.getItem(KEY));if(!db||db.version!==3)db=R.seed();}catch{db=R.seed();}
let filters={q:params.get('q')||'',category:params.get('category')||'',mode:'',sort:'default'},orderTab='all',adminTab='listings',authTab='login',toastTimer,scanControls=null,scanEvidence=null,scanMatched=null,scanStage='scan';
const me=()=>db.users.find(u=>u.id===db.activeUser),item=id=>db.items.find(i=>i.id===id),initials=n=>n.split(' ').slice(-2).map(x=>x[0]).join('');
function save(next){localStorage.setItem(KEY,JSON.stringify(next));db=next;}
try{save(db)}catch{}
function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),4200);}
function icons(){if(window.lucide)window.lucide.createIcons();}
function act(fn,message,redirect){try{const next=JSON.parse(JSON.stringify(db));const result=fn(next);save(next);closeModal();if(redirect){location.href=typeof redirect==='function'?redirect(result):redirect;return result;}render();if(message)toast(message);return result;}catch(e){const target=$('dialog[open] .form-error')||$('#main .form-error');if(target){target.textContent=e.message;target.hidden=false;target.scrollIntoView({block:'nearest'});}else toast(e.message);return null;}}
function closeModal(){if($('#modal').open)$('#modal').close();}
function modal(title,content){$('#modal').innerHTML=`<div class="modalhead"><h2 id="modal-title">${esc(title)}</h2><button class="iconbtn" data-action="close" aria-label="Đóng">${icon('x')}</button></div><div class="modalbody">${content}</div>`;$('#modal').showModal();icons();}
const err='<p class="error form-error" role="alert" hidden></p>';
function photo(i,cls=''){const valid=i.image&&/^data:image\/(png|jpeg|webp);base64,/.test(i.image);return `<div class="productart p${i.photo||0} ${valid?'custom':''} ${cls}" role="img" aria-label="${esc(i.name)}" ${valid?`style="background-image:url('${i.image}')"`:''}></div>`;}
function empty(title,text,link,label='Khám phá vật phẩm'){return `<div class="empty">${icon('package-open')}<h3>${esc(title)}</h3><p>${esc(text)}</p>${link?`<a class="btn outline" href="${link}">${esc(label)}</a>`:''}</div>`;}
function header(){const u=me();return `<header class="header"><div class="container nav"><a class="brand" href="index.html" aria-label="Rentie trang chủ">Rentie<span style="color:var(--accent)">.</span></a><nav class="navlinks" aria-label="Điều hướng chính"><a href="catalog.html" class="${['home','catalog','item'].includes(page)?'active':''}">Khám phá</a><a href="guide.html" class="${page==='guide'?'active':''}">Cách thuê đồ</a><a href="dashboard.html" class="${['dashboard','orders','wallet','warehouse','admin','inventory','disputes'].includes(page)?'active':''}">Không gian của tôi</a></nav><div class="navright"><button class="iconbtn" data-action="theme" title="Đổi giao diện sáng tối" aria-label="Đổi giao diện sáng tối">${icon('sun-moon')}</button><a class="iconbtn" href="scan.html" title="Quét mã" aria-label="Quét mã giao nhận">${icon('scan-line')}</a><a class="btn outline publish-nav" href="publish.html">${icon('plus')}Đăng vật phẩm</a><a class="iconbtn" href="account.html" title="Tài khoản" aria-label="Mở tài khoản">${u?`<span class="avatar">${esc(initials(u.name))}</span>`:icon('user-round')}</a><button class="iconbtn navtoggle" data-action="menu" aria-label="Mở menu" aria-expanded="false">${icon('menu')}</button></div></div></header><div class="demo"><div class="container"><span>Bản trình diễn <span class="longlabel">· Không giao dịch tiền thật</span></span><label>Thử vai trò <select id="demo-user" aria-label="Chọn tài khoản trình diễn">${db.users.filter(x=>x.status==='active').map(x=>`<option value="${x.id}" ${u?.id===x.id?'selected':''}>${esc(x.name)} · ${x.role==='student'?'Sinh viên':x.role==='staff'?'Thủ kho':'Admin'}</option>`).join('')}${!u?'<option value="" selected>Khách</option>':''}</select></label></div></div>`;}
function footer(){return `<footer class="footer"><div class="container"><div class="footergrid"><div><a href="index.html" class="brand">Rentie.</a><p>Đồ dùng cho việc học, câu lạc bộ và những trải nghiệm trong trường. Thuê khi cần, chia sẻ khi chưa dùng.</p></div><div><h3>Khám phá Rentie</h3><a href="catalog.html">Vật phẩm cho thuê</a><a href="publish.html">Đăng vật phẩm</a><a href="guide.html">Cách thuê và ký gửi</a></div><div><h3>Hỗ trợ giao nhận</h3><a href="scan.html">Quét mã giao nhận</a><a href="disputes.html">Khiếu nại của tôi</a><a href="sitemap.html">Sơ đồ website</a></div></div><div class="footnote">Đồ án Phân tích thiết kế hệ thống · Ảnh và dữ liệu minh họa · Một quầy Rentie tại thư viện trường.</div></div></footer>`;}
const panelPages=['dashboard','orders','wallet','inventory','warehouse','admin','disputes'];
function sidebar(){const u=me(),links=[['dashboard','layout-dashboard','Tổng quan'],['orders','clipboard-list','Đơn thuê'],...(u?.role==='student'?[['inventory','package','Đồ của tôi'],['wallet','wallet','Ví Rentie']]:[]),...(u?.role==='staff'?[['warehouse','warehouse','Quầy ký gửi']]:[]),...(u?.role==='admin'?[['admin','settings-2','Quản trị']]:[]),['disputes','messages-square','Khiếu nại'],['scan','scan-line','Quét mã giao nhận'],['account','user-round','Tài khoản']];return `<aside class="sidebar"><div class="profile"><span class="avatar">${esc(initials(u?.name||'Khách'))}</span><div><b>${esc(u?.name||'Khách')}</b><span>${u?.role==='student'?'Sinh viên':u?.role==='staff'?'Thủ kho':'Quản trị viên'}</span></div></div><div class="sidecaption">Không gian làm việc</div>${links.map(([p,i,t])=>`<a class="sidelink ${page===p?'active':''}" href="${p}.html">${icon(i)}${t}</a>`).join('')}<div class="sidebottom">${icon('info')}<p>Dữ liệu mẫu được lưu trên trình duyệt này. Bạn có thể đặt lại ở trang Tài khoản.</p></div></aside>`;}
function mobilebar(){return `<nav class="mobilebottom" aria-label="Điều hướng nhanh">${[['dashboard','layout-dashboard','Tổng quan'],['orders','clipboard-list','Đơn thuê'],['scan','scan-line','Quét mã'],[me()?.role==='staff'?'warehouse':me()?.role==='admin'?'admin':'inventory','package','Quản lý'],['account','user-round','Tài khoản']].map(([p,i,t])=>`<a href="${p}.html" class="${p===page?'active':''}">${icon(i)}${t}</a>`).join('')}</nav>`;}
function dashhead(title,desc,action=''){return `<div class="dashhead"><div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;}
function requireRole(...roles){const u=me();if(!u)return empty('Đăng nhập để tiếp tục','Chọn tài khoản trình diễn hoặc đăng nhập bằng tài khoản demo.','account.html','Đăng nhập');if(u.status!=='active')return empty('Tài khoản đang bị khóa','Hãy liên hệ quản trị viên hoặc chọn tài khoản demo khác.');if(!roles.includes(u.role))return empty('Khu vực dành cho '+roles.map(r=>r==='staff'?'thủ kho':r==='admin'?'Admin':'sinh viên').join(' / '),'Bạn có thể chọn đúng vai trò ở thanh “Thử vai trò” phía trên.');return '';}
function productCard(i){const favorites=db.favorites?.[me()?.id]||[];return `<article class="product"><a href="item.html?id=${i.id}">${photo(i)}<h3 class="product-name">${esc(i.name)}</h3></a><button class="heart ${favorites.includes(i.id)?'saved':''}" data-action="favorite" data-id="${i.id}" aria-label="${favorites.includes(i.id)?'Bỏ':'Lưu'} yêu thích ${esc(i.name)}">${icon('heart')}</button><div class="product-price">${V(i.rate)} <small>/ ${unit(i)}</small></div><div class="product-deposit">Cọc ${V(i.deposit)}</div><div class="product-tail"><span class="product-meta">${icon(i.mode==='counter'?'store':'handshake')}${mode(i)}</span><span class="tag">${i.minScore}+ điểm</span></div></article>`;}
function visibleProducts(){let list=db.items.filter(i=>i.status==='approved'&&db.users.find(u=>u.id===i.owner)?.status==='active');if(filters.q){const q=filters.q.toLocaleLowerCase('vi');list=list.filter(i=>(i.name+' '+i.description+' '+i.category).toLocaleLowerCase('vi').includes(q));}if(filters.category)list=list.filter(i=>i.category===filters.category);if(filters.mode)list=list.filter(i=>i.mode===filters.mode);if(filters.sort==='price')list.sort((a,b)=>a.rate-b.rate);if(filters.sort==='deposit')list.sort((a,b)=>a.deposit-b.deposit);if(filters.sort==='score')list.sort((a,b)=>a.minScore-b.minScore);return list;}
function categories(){return `<div class="categorybar" role="group" aria-label="Lọc theo danh mục">${['',...db.categories.filter(c=>!db.hiddenCategories?.includes(c))].map(c=>`<button data-action="category" data-category="${esc(c)}" class="${filters.category===c?'active':''}">${esc(c||'Tất cả vật phẩm')}</button>`).join('')}</div>`;}
function search(){return `<form id="search-form" class="searchbar">${icon('search')}<input name="q" value="${esc(filters.q)}" placeholder="Bạn muốn thuê gì?" aria-label="Tìm vật phẩm"><button class="btn" type="submit">Tìm đồ ${icon('arrow-up-right')}</button></form>`;}
function home(){const products=visibleProducts();return `<div class="container"><section class="intro"><div class="intro-top"><div><h1>Món đồ bạn cần.<br>Ngay trong trường.</h1><p>Thuê đồ cho việc học và những kế hoạch cuối tuần.</p></div><div class="intro-note">${icon('handshake')}<p>Chọn tự giao nhận với chủ đồ hoặc nhận đồ đã kiểm định tại quầy.</p><a href="guide.html" class="textlink">Tìm hiểu cách thuê</a></div></div>${search()}</section><section class="showroom" aria-label="Vật phẩm nổi bật">${categories()}<div id="product-results">${products.length?`<div class="productgrid">${products.slice(0,4).map(productCard).join('')}</div>`:empty('Chưa có vật phẩm phù hợp','Thử một từ khóa hoặc danh mục khác.')}<div class="flex between mt"><span class="small muted">Ảnh và giá minh họa cho đồ án</span><a href="catalog.html" class="textlink small">Xem tất cả vật phẩm ${icon('arrow-right')}</a></div></div></section><section class="section"><div class="section-title"><h2>Hai cách thuê. Cùng một hồ sơ rõ ràng.</h2><p>Chọn cách giao nhận phù hợp với lịch học của bạn.</p></div><div class="two-paths"><article class="path">${icon('handshake','largeicon')}<div class="sub">P2P · TỰ GIAO NHẬN</div><h3>Hẹn nhau ngay trong trường</h3><p>Chủ đồ và người thuê tự hẹn địa điểm, cùng ghi nhận tình trạng và xác nhận giao nhận.</p><a class="textlink small" href="catalog.html?mode=p2p">Tìm đồ P2P ${icon('arrow-up-right')}</a></article><article class="path">${icon('store','largeicon')}<div class="sub">KÝ GỬI · NHẬN TẠI QUẦY</div><h3>Có thủ kho cùng kiểm tra</h3><p>Đồ được tiếp nhận và lưu tại quầy. Thủ kho đối chiếu mã, phụ kiện và ảnh khi giao, nhận trả.</p><a class="textlink small" href="catalog.html?mode=counter">Tìm đồ tại quầy ${icon('arrow-up-right')}</a></article></div></section><section class="section"><div class="section-title"><h2>Từ một lịch hẹn đến một món đồ hữu ích.</h2></div><div class="workflow"><div><b>01 / CHỌN</b><h3>Tìm món phù hợp</h3><p>Xem giá, cọc, tình trạng và điểm uy tín yêu cầu.</p></div><div><b>02 / ĐẶT</b><h3>Giữ lịch thuê</h3><p>Chọn thời gian và thanh toán bằng ví mô phỏng.</p></div><div><b>03 / NHẬN</b><h3>Đối chiếu cùng nhau</h3><p>Kiểm tra phụ kiện, lưu ảnh và xác nhận giao nhận.</p></div><div><b>04 / TRẢ</b><h3>Trả đồ, nhận lại cọc</h3><p>Đối soát hiện trạng và xem đầy đủ kết quả tất toán.</p></div></div></section></div>`;}
function catalog(){return `<div class="container"><div class="pagehead"><div class="breadcrumb"><a href="index.html">Trang chủ</a>${icon('chevron-right')}Khám phá</div><h1>Tìm món đồ cho kế hoạch của bạn.</h1>${search()}</div><section class="section" style="padding-top:22px">${categories()}<div class="filterrow"><span class="small muted" id="result-count">${visibleProducts().length} vật phẩm phù hợp</span><div class="filters"><label><span class="hidden">Hình thức giao nhận</span><select id="filter-mode" class="field"><option value="">Mọi hình thức</option><option value="p2p" ${filters.mode==='p2p'?'selected':''}>Tự giao nhận P2P</option><option value="counter" ${filters.mode==='counter'?'selected':''}>Nhận tại quầy</option></select></label><label><span class="hidden">Sắp xếp</span><select id="filter-sort" class="field"><option value="default">Mới đăng</option><option value="price" ${filters.sort==='price'?'selected':''}>Đơn giá tăng dần</option><option value="deposit" ${filters.sort==='deposit'?'selected':''}>Tiền cọc thấp trước</option><option value="score" ${filters.sort==='score'?'selected':''}>Điểm yêu cầu thấp</option></select></label></div></div><p class="hint mb">Đơn giá theo giờ/ngày được ghi ở từng vật phẩm; hãy so sánh cùng đơn vị khi chọn.</p><div id="catalog-results">${visibleProducts().length?`<div class="productgrid">${visibleProducts().map(productCard).join('')}</div>`:empty('Không tìm thấy vật phẩm','Thử bỏ bớt bộ lọc hoặc tìm từ khóa khác.')}</div></section></div>`;}
function detail(){const i=item(params.get('id'))||db.items[0],owner=db.users.find(u=>u.id===i.owner),start=stamp(Date.now()+R.HOUR),end=stamp(Date.now()+R.HOUR+(i.unit==='hour'?2*R.HOUR:R.DAY));const occupied=db.bookings.filter(b=>b.itemId===i.id&&['booked','active','returned','disputed'].includes(b.status));return `<div class="container"><div class="pagehead breadcrumb"><a href="catalog.html">Khám phá</a>${icon('chevron-right')}${esc(i.category)}</div><div class="detailgrid"><div class="detailgallery">${photo(i,'detailart')}<small>Ảnh ${i.image?'do chủ đồ cung cấp':'minh họa cho đồ án'}. Xem ảnh tình trạng khi giao nhận.</small><div class="surface"><h3>Về vật phẩm</h3><p class="small muted">${esc(i.description)}</p><div class="line"></div><h3>Phụ kiện đi kèm</h3><p class="small">${esc(i.accessories)}</p><p class="small muted">${esc(i.condition)}</p></div><div class="surface"><h3>Lịch đã được giữ</h3>${occupied.length?occupied.map(b=>`<p class="small">${date(b.start)} → ${date(b.end)} ${badge(b.status)}</p>`).join(''):'<p class="small muted">Chưa có lịch đặt. Bạn có thể chọn thời gian phù hợp.</p>'}</div></div><div class="detailinfo"><span class="tag">${icon(i.mode==='counter'?'store':'handshake')}${mode(i)}</span><h1>${esc(i.name)}</h1><div class="detailprice">${V(i.rate)} <small>/ ${unit(i)}</small></div><div class="detailstats"><div><b>${V(i.deposit)}</b><span>Tiền cọc tạm giữ</span></div><div><b>${i.minScore}/100</b><span>Uy tín tối thiểu</span></div></div><div class="owner"><span class="avatar">${esc(initials(owner.name))}</span><div><p><b>${esc(owner.name)}</b></p><p class="muted">${i.mode==='counter'?(i.checked?'Đã tiếp nhận và kiểm định tại quầy':'Chờ kiểm định tại quầy'):(['approved','hidden'].includes(i.status)?'Tin đã được duyệt · Hai bên tự kiểm tra đồ':'Tin đang chờ kết quả duyệt')}</p></div></div><form id="booking-form" class="surface"><h3>Chọn lịch thuê</h3><input type="hidden" name="itemId" value="${i.id}"><div class="formgrid"><div class="formrow"><label class="fieldlabel" for="rent-start">Nhận đồ</label><input id="rent-start" class="field" name="start" type="datetime-local" value="${start}" required></div><div class="formrow"><label class="fieldlabel" for="rent-end">Trả đồ</label><input id="rent-end" class="field" name="end" type="datetime-local" value="${end}" required></div></div>${i.mode==='p2p'?'<div class="formrow"><label class="fieldlabel" for="location">Địa điểm hẹn trong trường</label><input class="field" id="location" name="location" value="Sảnh thư viện" required maxlength="100"></div>':'<p class="small muted">Giao nhận tại quầy Rentie, thư viện trường.</p>'}<div id="rental-quote" class="quote"></div>${err}<button class="btn block" ${i.status!=='approved'?'disabled':''}>Tạo đơn thuê ${icon('arrow-right')}</button><p class="hint">Đơn chỉ giữ lịch sau khi bạn thanh toán tiền thuê và cọc.</p></form></div></div></div>`;}
function updateQuote(){const f=$('#booking-form');if(!f)return;try{const i=item(f.itemId.value),q=R.quote(i,toISO(f.start.value),toISO(f.end.value));$('#rental-quote').innerHTML=`<div class="moneyline"><span>${q.units} ${unit(i)} × ${V(i.rate)}</span><b>${V(q.fee)}</b></div><div class="moneyline"><span>Cọc được tạm giữ</span><b>${V(q.deposit)}</b></div><div class="moneyline total"><span>Tổng thanh toán</span><span>${V(q.total)}</span></div>`;}catch{$('#rental-quote').textContent='Chọn thời gian nhận và trả hợp lệ.';}}
function stats(){const u=me(),bs=db.bookings.filter(b=>u.role==='student'?[b.owner,b.renter].includes(u.id):true),cap=R.capacity(db);const rows=u.role==='student'?[[V(u.balance),'Số dư khả dụng','wallet','Dùng cho tiền thuê và cọc'],[u.score+'/100','Điểm uy tín','shield-check','Bắt đầu 100 · Tối đa 100'],[bs.filter(b=>['booked','active'].includes(b.status)).length,'Đơn đang theo dõi','clipboard-list','Chờ nhận hoặc đang thuê'],[db.items.filter(i=>i.owner===u.id).length,'Vật phẩm của bạn','package','Gồm tin đã đăng và chờ duyệt']]:[[bs.filter(b=>b.status==='booked').length,'Chờ bàn giao','scan-line','Đơn đã giữ lịch'],[bs.filter(b=>b.status==='active').length,'Đang được thuê','package-open','Theo dõi thời hạn trả'],[cap.count+'/'+db.policies.maxCount,'Chỗ ký gửi đã dùng','warehouse','Tính cả chỗ dự phòng nhận trả'],[db.disputes.filter(d=>d.status==='open'&&(u.role==='admin'||d.level==='staff')).length,'Khiếu nại chờ xử lý','messages-square','Theo đúng cấp xử lý']];return `<div class="stats">${rows.map(([n,l,i,s])=>`<div class="stat"><div class="label">${l}${icon(i)}</div><strong>${n}</strong><small>${s}</small></div>`).join('')}</div>`;}
function dashboard(){const denied=requireRole('student','staff','admin');if(denied)return denied;const u=me(),list=db.bookings.filter(b=>u.role==='student'?[b.renter,b.owner].includes(u.id):true).slice(0,5);return `${dashhead('Chào '+esc(u.name.split(' ').slice(-2).join(' '))+',','Theo dõi việc thuê và chia sẻ đồ dùng của bạn hôm nay.',`<a href="${u.role==='student'?'publish':'scan'}.html" class="btn">${icon(u.role==='student'?'plus':'scan-line')}${u.role==='student'?'Đăng vật phẩm':'Quét mã'}</a>`)}${stats()}<div class="dashgrid"><div><div class="tablebox"><div class="boxhead"><h2>Đơn thuê gần đây</h2><a href="orders.html" class="textlink small">Xem tất cả</a></div>${orderTable(list)}</div><div class="surface mt"><h3>Mọi giao nhận đều có đối soát</h3><p class="small muted">Quét mã để tìm đúng đơn. Đối chiếu vật phẩm, phụ kiện và ảnh hiện trạng trước khi xác nhận.</p><a class="btn outline small" href="scan.html">${icon('scan-line')}Mở quét mã</a></div></div><div><div class="surface"><h3>Thông báo của bạn</h3>${db.notifications.filter(n=>n.user===u.id).slice(0,4).map(n=>`<div class="activity"><span class="iconbox">${icon('bell')}</span><div><p>${esc(n.text)}</p><small class="muted">${date(n.at)}</small></div></div>`).join('')||'<p class="small muted">Chưa có thông báo mới.</p>'}</div><div class="surface mt"><h3>Quy tắc đang áp dụng</h3><p class="small muted">Phí vận hành ${db.policies.fee}% tiền thuê. Cọc được tạm giữ riêng. Điểm uy tín chỉ đổi khi tất toán.</p><a href="guide.html#policies" class="textlink small">Xem quy tắc thuê đồ</a></div></div></div>`;}
function orderTable(list){if(!list.length)return empty('Chưa có đơn thuê','Các đơn của bạn sẽ xuất hiện ở đây.','catalog.html');return `<div class="tablewrap"><table class="datatable"><thead><tr><th>Vật phẩm / mã đơn</th><th>Hạn trả</th><th>Trạng thái</th><th></th></tr></thead><tbody>${list.map(b=>`<tr><td><div class="flex">${photo(item(b.itemId),'miniphoto')}<div class="namecell"><b>${esc(item(b.itemId).name)}</b><span class="muted mono">${b.id}</span></div></div></td><td>${date(b.end)}</td><td>${badge(b.status,b.status==='pending'?'Chờ thanh toán':null)}</td><td><button class="iconbtn" data-action="order-detail" data-id="${b.id}" aria-label="Xem đơn ${b.id}">${icon('arrow-up-right')}</button></td></tr>`).join('')}</tbody></table></div>`;}
function orderButtons(b){const u=me(),isRenter=b.renter===u.id,isOwner=b.owner===u.id,isStaff=u.role==='staff';let h=`<button class="btn outline small" data-action="order-detail" data-id="${b.id}">Chi tiết</button>`;if(b.status==='pending'&&isRenter)h+=`<button class="btn small" data-action="pay" data-id="${b.id}">Thanh toán ${V(b.fee+b.deposit)}</button>`;if(['pending','booked'].includes(b.status)&&isRenter&&!b.handoverBy.length)h+=`<button class="btn outline small" data-action="cancel" data-id="${b.id}">Hủy đơn</button>`;if(b.status==='booked'){h+=`<button class="btn outline small" data-action="qr" data-id="${b.id}">${icon('qr-code')}Mã giao nhận</button>`;if((b.mode==='counter'&&isStaff)||(b.mode==='p2p'&&(isOwner||isRenter)))h+=`<a class="btn small" href="scan.html?order=${b.id}&mode=handover">Xác nhận bàn giao</a>`;}if(b.status==='active'){if((b.mode==='counter'&&isStaff)||(b.mode==='p2p'&&isOwner&&!b.returnBy.length))h+=`<a class="btn small" href="scan.html?order=${b.id}&mode=return">Nhận trả đồ</a>`;if(b.mode==='p2p'&&isRenter&&b.returnBy.includes(b.owner))h+=`<button class="btn small" data-action="confirm-return" data-id="${b.id}">Xác nhận hiện trạng trả</button>`;}if(b.status==='returned'&&((b.mode==='counter'&&isStaff)||(b.mode==='p2p'&&isOwner)||u.role==='admin'))h+=`<button class="btn small" data-action="settle" data-id="${b.id}">Tất toán đơn</button>`;if(['active','returned'].includes(b.status)&&(isOwner||isRenter))h+=`<button class="btn outline small" data-action="complain" data-id="${b.id}">Gửi khiếu nại</button>`;return h;}
function orders(){const denied=requireRole('student','staff','admin');if(denied)return denied;const u=me(),all=db.bookings.filter(b=>u.role==='student'?[b.renter,b.owner].includes(u.id):true),list=all.filter(b=>orderTab==='all'||(orderTab==='current'?['pending','booked','active','returned','disputed'].includes(b.status):b.status==='completed'||b.status==='cancelled'));return `${dashhead('Đơn thuê','Lịch thuê, giao nhận và tiền cọc trong cùng một hồ sơ.')}<div class="tabs">${[['all','Tất cả'],['current','Đang theo dõi'],['done','Đã kết thúc']].map(([v,t])=>`<button class="${orderTab===v?'active':''}" data-action="order-tab" data-tab="${v}">${t}</button>`).join('')}</div>${list.length?list.map(b=>`<article class="ordercard"><div class="flex alignstart">${photo(item(b.itemId))}<div class="spacer"><div class="flex between wrap"><small class="muted mono">${b.id} · ${mode(b)}</small>${badge(b.status,b.status==='pending'?'Chờ thanh toán':null)}</div><h3>${esc(item(b.itemId).name)}</h3><span class="small muted">${esc(b.location)}</span></div></div><div class="summary"><div><span class="muted">Nhận dự kiến</span><b>${date(b.start)}</b></div><div><span class="muted">Trả trước</span><b>${date(b.end)}</b></div><div><span class="muted">Tiền thuê / Cọc</span><b>${V(b.fee)} / ${V(b.deposit)}</b></div></div>${b.status==='booked'&&b.handoverBy.length?'<p class="hint">Một bên đã xác nhận bàn giao. Đang chờ bên còn lại.</p>':''}${b.status==='active'&&b.returnBy.length?'<p class="hint">Đã có hiện trạng trả. Người thuê cần đối chiếu và xác nhận hoặc gửi khiếu nại.</p>':''}<div class="actionrow">${orderButtons(b)}</div></article>`).join(''):empty('Chưa có đơn ở mục này','Khám phá vật phẩm và chọn khoảng thời gian bạn cần.','catalog.html')}`;}
function wallet(){const denied=requireRole('student');if(denied)return denied;const u=me(),entries=db.ledger.filter(e=>e.user===u.id);return `${dashhead('Ví Rentie','Theo dõi số dư, tiền cọc tạm giữ và từng khoản biến động.')}<div class="dashgrid"><div class="walletbalance"><span class="small subtle">Số dư khả dụng · Ví mô phỏng</span><h2>${V(u.balance)}</h2><div class="flex wrap"><button class="btn" data-action="transfer" data-type="topup">${icon('plus')}Nạp tiền</button><button class="btn outline" data-action="transfer" data-type="withdraw">${icon('arrow-up-right')}Rút tiền</button></div></div><div class="surface mb"><span class="small muted">Tiền cọc đang tạm giữ</span><h2 class="mt">${V(u.held)}</h2><p class="small muted">Khoản này được tách khỏi số dư khả dụng. Phần cọc còn lại sẽ được hoàn sau đối soát.</p></div></div><div class="tablebox"><div class="boxhead"><h2>Lịch sử giao dịch</h2><span class="small muted">${entries.length} bút toán</span></div><div class="tablewrap"><table class="datatable"><thead><tr><th>Nội dung</th><th>Đơn thuê</th><th>Thời gian</th><th>Thay đổi khả dụng</th><th>Thay đổi tạm giữ</th></tr></thead><tbody>${entries.map(e=>`<tr><td>${esc(e.note)}</td><td class="mono">${e.bookingId||'Không áp dụng'}</td><td>${date(e.at)}</td><td><b>${e.delta>0?'+':''}${V(e.delta)}</b></td><td>${e.heldDelta>0?'+':''}${V(e.heldDelta)}</td></tr>`).join('')||'<tr><td colspan="5">Chưa có biến động.</td></tr>'}</tbody></table></div></div>`;}
function inventory(){const denied=requireRole('student');if(denied)return denied;const list=db.items.filter(i=>i.owner===me().id);return `${dashhead('Đồ của tôi','Quản lý tin đăng P2P và các đợt ký gửi.',`<a class="btn" href="publish.html">${icon('plus')}Đăng vật phẩm</a>`)}${list.length?list.map(i=>`<article class="ordercard"><div class="flex alignstart">${photo(i)}<div class="spacer"><div class="flex between wrap"><span class="small muted mono">${i.id} · ${mode(i)}</span>${badge(i.status)}</div><h3>${esc(i.name)}</h3><span class="small">${V(i.rate)} / ${unit(i)} · Cọc ${V(i.deposit)}</span>${i.rejection?`<p class="hint">Lý do: ${esc(i.rejection)}</p>`:''}</div></div><div class="actionrow"><a class="btn outline small" href="publish.html?id=${i.id}">Chỉnh sửa</a>${['approved','hidden'].includes(i.status)?`<button class="btn outline small" data-action="toggle-item" data-id="${i.id}">${i.status==='hidden'?'Hiện lại':'Ẩn tin'}</button>`:''}<button class="btn outline small" data-action="item-qr" data-id="${i.id}">${icon('qr-code')}Mã vật phẩm</button></div>${db.consignments.filter(c=>c.itemId===i.id).map(c=>`<div class="notice small"><div class="flex between wrap"><b>Đợt ${c.id}</b>${badge(c.status,c.status==='active'?'Đang lưu ký':null)}</div>${c.deadline?`<p class="hint">Hạn lưu ký: ${date(c.deadline)} · ${i.volume} lít</p>`:''}<div class="actionrow">${c.status==='active'?`<button class="btn outline small" data-action="consignment" data-id="${c.id}" data-type="renew">Gia hạn 30 ngày</button><button class="btn outline small" data-action="consignment" data-id="${c.id}" data-type="request">Yêu cầu nhận lại</button>`:''}${c.status==='closed'&&!db.consignments.some(d=>d.itemId===i.id&&['pending','active','pickup'].includes(d.status))?`<button class="btn outline small" data-action="consignment" data-id="${c.id}" data-type="resubmit">Ký gửi lại</button>`:''}</div></div>`).join('')}</article>`).join(''):empty('Bạn chưa đăng vật phẩm','Một món đồ ít dùng có thể hữu ích cho người khác.','publish.html','Đăng vật phẩm')}`;}
function evidenceField(id='evidence'){return `<div class="evidencefield"><label for="${id}">Ảnh hiện trạng / bằng chứng</label><input id="${id}" name="evidenceFile" type="file" accept="image/png,image/jpeg,image/webp" capture="environment"><p class="hint">Chọn ảnh hoặc chụp bằng camera. Không tải thông tin cá nhân nhạy cảm.</p><button type="button" class="btn outline small" data-action="sample-evidence">Dùng ảnh mẫu để thử</button><input type="hidden" name="evidence" value=""><div class="evidencepreview"></div></div>`;}
function publishPage(){const denied=requireRole('student');if(denied)return `<div class="container section">${denied}</div>`;const i=item(params.get('id'));if(i&&i.owner!==me().id)return `<div class="container section">${empty('Không thể sửa vật phẩm này','Chỉ chủ sở hữu mới được chỉnh sửa tin.')}</div>`;const val=(k,d='')=>esc(i?.[k]??d);return `<div class="container"><div class="pagehead"><div class="breadcrumb"><a href="inventory.html">Đồ của tôi</a>${icon('chevron-right')}${i?'Chỉnh sửa':'Đăng vật phẩm'}</div><h1>${i?'Chỉnh sửa vật phẩm':'Cho món đồ của bạn thêm một cơ hội.'}</h1><p class="muted">Thông tin rõ ràng giúp người thuê chọn đúng và giao nhận dễ hơn.</p></div><section class="section" style="padding-top:15px"><div class="detailgrid publishgrid"><form id="publish-form" class="surface"><input type="hidden" name="id" value="${val('id')}"><div class="formrow"><label class="fieldlabel" for="item-name">Tên vật phẩm</label><input class="field" id="item-name" name="name" minlength="4" maxlength="100" required value="${val('name')}" placeholder="Ví dụ: Máy chiếu mini kèm dây HDMI"></div><div class="formgrid"><div class="formrow"><label class="fieldlabel" for="category">Danh mục</label><select class="field" id="category" name="category">${db.categories.filter(c=>!db.hiddenCategories?.includes(c)).map(c=>`<option ${i?.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="formrow"><label class="fieldlabel" for="listing-mode">Hình thức cho thuê</label><select class="field" id="listing-mode" name="mode"><option value="p2p" ${i?.mode==='p2p'?'selected':''}>P2P · Tự giao nhận</option><option value="counter" ${i?.mode==='counter'?'selected':''}>Ký gửi tại quầy</option></select></div><div class="formrow"><label class="fieldlabel" for="unit">Đơn vị tính giá</label><select class="field" id="unit" name="unit"><option value="day" ${i?.unit==='day'?'selected':''}>Theo ngày (24 giờ)</option><option value="hour" ${i?.unit==='hour'?'selected':''}>Theo giờ (60 phút)</option></select></div><div class="formrow"><label class="fieldlabel" for="rate">Giá thuê mỗi đơn vị (đ)</label><input class="field" id="rate" name="rate" type="number" min="1000" max="10000000" step="1000" value="${val('rate',50000)}" required></div><div class="formrow"><label class="fieldlabel" for="deposit">Tiền cọc (đ)</label><input class="field" id="deposit" name="deposit" type="number" min="0" max="50000000" step="1000" value="${val('deposit',300000)}" required></div><div class="formrow"><label class="fieldlabel" for="minScore">Uy tín tối thiểu (0–100)</label><input class="field" id="minScore" name="minScore" type="number" min="0" max="100" value="${val('minScore',70)}" required></div><div class="formrow"><label class="fieldlabel" for="volume">Dung tích đóng gói (lít)</label><input class="field" id="volume" name="volume" type="number" min="0.1" step="0.1" max="360" value="${val('volume',10)}" required><p class="hint">Dùng để kiểm tra sức chứa khi ký gửi.</p></div><div class="formrow"><label class="fieldlabel" for="location">Địa điểm hẹn P2P</label><input class="field" id="location" name="location" value="${val('location','Sảnh thư viện')}" maxlength="100"></div></div><div class="formrow"><label class="fieldlabel" for="appointment">Dự kiến mang đến quầy (chỉ khi ký gửi)</label><input class="field" id="appointment" name="appointmentAt" type="datetime-local" value="${stamp(Date.now()+R.DAY)}"><p class="hint">Đây là lịch đề nghị; thủ kho xác nhận tiếp nhận khi bạn mang đồ tới.</p></div><div class="formrow"><label class="fieldlabel" for="description">Mô tả</label><textarea class="field" id="description" name="description" maxlength="1200" required>${val('description')}</textarea></div><div class="formrow"><label class="fieldlabel" for="accessories">Phụ kiện đi kèm</label><input class="field" id="accessories" name="accessories" value="${val('accessories')}" maxlength="250" required></div><div class="formrow"><label class="fieldlabel" for="condition">Tình trạng hiện tại</label><input class="field" id="condition" name="condition" value="${val('condition','Hoạt động tốt, có dấu sử dụng nhẹ.')}" maxlength="250"></div><div class="formrow"><label class="fieldlabel" for="photo">Ảnh minh họa để trình diễn</label><select class="field" id="photo" name="photo">${['Máy ảnh','Máy chiếu','Vợt cầu lông','Guitar','Loa','Chân máy'].map((x,n)=>`<option value="${n}" ${i?.photo===n?'selected':''}>${x}</option>`).join('')}</select><label class="fieldlabel mt" for="item-image">Hoặc chọn ảnh vật phẩm của bạn</label><input id="item-image" name="itemImage" type="file" accept="image/png,image/jpeg,image/webp"><input type="hidden" name="image" value="${val('image')}"><p class="hint">Ảnh sẽ được lưu trong bản demo trên trình duyệt.</p></div>${err}<button class="btn block">Gửi xét duyệt ${icon('arrow-right')}</button></form><aside><div class="surface"><h3>Tin của bạn sẽ đi đâu?</h3><div class="activity"><span class="iconbox">${icon('handshake')}</span><div><b class="small">Tự giao nhận P2P</b><p class="small muted">Admin kiểm tra nội dung tin. Khi được duyệt, bạn và người thuê tự hẹn giao nhận.</p></div></div><div class="activity"><span class="iconbox">${icon('store')}</span><div><b class="small">Ký gửi tại quầy</b><p class="small muted">Mang vật phẩm đến quầy. Thủ kho kiểm định và kiểm tra cả số chỗ lẫn dung tích trước khi nhận.</p></div></div></div><div class="notice"><b>Giá được lưu theo từng đơn</b><p class="small">Mỗi vật phẩm dùng một đơn vị giờ hoặc ngày. Đơn đã tạo giữ nguyên giá và cọc tại thời điểm đặt.</p></div></aside></div></section></div>`;}
function warehouse(){const no=requireRole('staff');if(no)return no;const c=R.capacity(db);return `${dashhead('Quầy ký gửi','Một điểm nhận đồ tại thư viện. Chỗ trống bao gồm phần dự phòng cho đồ đang cho thuê.')}<div class="stats"><div class="stat"><span>Số món đang giữ chỗ</span><h2>${c.count} / ${db.policies.maxCount}</h2></div><div class="stat"><span>Dung tích đã giữ</span><h2>${c.volume} / ${db.policies.maxVolume} L</h2></div></div><h2 class="mt">Chờ kiểm định</h2>${listingQueue('counter')}<h2 class="mt">Sổ lưu ký</h2><div class="tablebox tablewrap"><table class="datatable"><thead><tr><th>Vật phẩm</th><th>Đợt / hạn lưu ký</th><th>Dung tích</th><th>Trạng thái</th><th></th></tr></thead><tbody>${db.consignments.map(c=>`<tr><td>${esc(item(c.itemId).name)}</td><td>${c.id}<br><span class="small muted">${date(c.deadline)}</span></td><td>${item(c.itemId).volume} L</td><td>${badge(c.status,c.status==='active'?'Đang lưu ký':null)}</td><td><button class="btn outline small" data-action="item-qr" data-id="${c.itemId}">Mã đồ</button>${c.status==='pickup'?` <button class="btn small" data-action="consignment" data-id="${c.id}" data-type="return">Trả cho chủ</button>`:''}</td></tr>`).join('')}</tbody></table></div>`;}
function listingQueue(mode){const list=db.items.filter(i=>i.mode===mode&&i.status==='pending');return list.map(i=>`<article class="ordercard"><div class="flex">${photo(i,'miniphoto')}<div class="spacer"><h3>${esc(i.name)}</h3><p class="small muted">${esc(R.user(db,i.owner).name)} · ${V(i.rate)}/${unit(i)} · Cọc ${V(i.deposit)} · ${i.volume} L</p><p class="small">${esc(i.description)}</p><p class="small">Phụ kiện: ${esc(i.accessories)}</p>${i.mode==='counter'?`<p class="small muted">Lịch mang tới dự kiến: ${date(db.consignments.find(c=>c.itemId===i.id&&c.status==='pending')?.appointmentAt)}</p>`:''}</div></div><div class="actionrow"><button class="btn small" data-action="approve" data-id="${i.id}">${mode==='counter'?'Kiểm định và nhận':'Duyệt nội dung'}</button><button class="btn outline small" data-action="reject" data-id="${i.id}">Từ chối</button></div></article>`).join('')||'<div class="surface"><p class="muted">Không có vật phẩm chờ duyệt.</p></div>';}
function admin(){const no=requireRole('admin');if(no)return no;let body='';if(adminTab==='listings')body=listingQueue('p2p');if(adminTab==='users')body=`<div class="tablebox tablewrap"><table class="datatable"><thead><tr><th>Tài khoản</th><th>Mã sinh viên</th><th>Uy tín</th><th>Trạng thái</th><th></th></tr></thead><tbody>${db.users.map(u=>`<tr><td><b>${esc(u.name)}</b><br>${esc(u.email)}</td><td>${esc(u.studentId||u.role)}</td><td>${u.score??'—'}</td><td>${u.status==='active'?'Hoạt động':'Đã khóa'}</td><td>${u.role==='student'?`<button class="btn outline small" data-action="lock-user" data-id="${u.id}">${u.status==='active'?'Khóa':'Mở khóa'}</button>`:''}</td></tr>`).join('')}</tbody></table></div>`;if(adminTab==='categories')body=`<div class="surface"><h2>Danh mục vật phẩm</h2><p class="hint">Ẩn danh mục khỏi bộ lọc và tin đăng mới. Các tin đã duyệt vẫn xem được trong Tất cả vật phẩm.</p>${db.categories.map(c=>`<div class="boxhead"><span>${esc(c)} ${db.hiddenCategories?.includes(c)?'<small class="muted">· Đã ẩn</small>':''}</span><div class="flex wrap"><button class="btn outline small" data-action="rename-category" data-name="${esc(c)}">Sửa</button><button class="btn outline small" data-action="hide-category" data-name="${esc(c)}">${db.hiddenCategories?.includes(c)?'Hiện':'Ẩn'}</button><button class="btn outline small" data-action="delete-category" data-name="${esc(c)}">Xóa</button></div></div>`).join('')}<form id="category-form" class="actionrow mt"><input class="field" name="name" placeholder="Tên danh mục mới" aria-label="Tên danh mục mới" required maxlength="40"><button class="btn">Thêm</button>${err}</form></div>`;if(adminTab==='settings')body=`<form id="settings-form" class="surface"><h2>Cấu hình hệ thống</h2><p class="muted small">Phí mới chỉ áp dụng cho đơn tạo sau khi lưu.</p>${[['fee','Phí vận hành (%)',0,30],['maxCount','Sức chứa (món)',1,1000],['maxVolume','Sức chứa (lít)',1,10000]].map(([n,l,min,max])=>`<div class="formrow"><label class="fieldlabel" for="${n}">${l}</label><input class="field" id="${n}" name="${n}" type="number" min="${min}" max="${max}" required value="${db.policies[n]}"></div>`).join('')}${err}<button class="btn">Lưu cấu hình</button></form>`;return `${dashhead('Quản trị hệ thống','Duyệt tin P2P, quản lý tài khoản và quy tắc vận hành.')}<div class="tabs">${[['listings','Duyệt tin'],['users','Tài khoản'],['categories','Danh mục'],['settings','Cấu hình']].map(([v,t])=>`<button data-action="admin-tab" data-tab="${v}" class="${adminTab===v?'active':''}">${t}</button>`).join('')}</div>${body}`;}
function proof(e){if(!e)return '<span class="muted small">Chưa có ảnh.</span>';return e.sample?`<div class="small">${photo({photo:e.photo||0,name:'Ảnh mẫu hiện trạng'},'proofthumb')}<span class="muted">Ảnh minh họa dùng thử</span></div>`:/^data:image\/(jpeg|png|webp);base64,/.test(e.src||'')?`<img class="proofthumb" src="${e.src}" alt="Ảnh hiện trạng do người dùng cung cấp">`:'';}
function disputes(){const no=requireRole('student','staff','admin');if(no)return no;const u=me(),list=db.disputes.filter(d=>u.role==='admin'||u.role==='staff'&&d.level==='staff'||u.role==='student'&&[R.booking(db,d.bookingId).owner,R.booking(db,d.bookingId).renter].includes(u.id));return `${dashhead('Khiếu nại','Hồ sơ đang xử lý sẽ tạm dừng tất toán.')}<div class="notice small">Thủ kho xử lý vụ việc ≤ 200.000đ và ≤ 30% cọc, không mất đồ, hai bên thống nhất bằng chứng. Trường hợp khác chuyển Admin.</div>${list.map(d=>`<article class="ordercard"><div class="flex between"><h3>${d.id} · ${d.bookingId}</h3>${badge(d.status)}</div><p>${esc(d.reason)}</p><p class="small muted">Giá trị: ${V(d.amount)} · Phụ trách: ${d.level==='admin'?'Admin':'Thủ kho'}</p>${proof(d.evidence)}${d.staffNote?`<p class="notice small">Ghi nhận thủ kho: ${esc(d.staffNote)}</p>`:''}${d.decision?`<p class="notice">Kết luận: ${esc(d.decision)}</p>`:''}${d.status==='open'&&['admin','staff'].includes(u.role)?`<button class="btn small mt" data-action="resolve" data-id="${d.id}">Xử lý hồ sơ</button>`:''}</article>`).join('')||empty('Chưa có khiếu nại','Mở chi tiết đơn thuê để gửi hồ sơ trước khi tất toán.')}`;}
function account(){const u=me();if(!u)return `<div class="container section"><div class="authwrap surface"><h1>Chào bạn đến Rentie.</h1><p class="muted">Đồ dùng tốt, thêm một người dùng.</p><div class="tabs"><button data-action="auth-tab" data-tab="login" class="${authTab==='login'?'active':''}">Đăng nhập</button><button data-action="auth-tab" data-tab="register" class="${authTab==='register'?'active':''}">Đăng ký</button></div><form id="auth-form"><input type="hidden" name="type" value="${authTab}">${authTab==='register'?'<div class="formrow"><label class="fieldlabel" for="auth-name">Họ và tên</label><input class="field" id="auth-name" name="name" required minlength="3"></div><div class="formrow"><label class="fieldlabel" for="student-id">Mã sinh viên</label><input class="field" id="student-id" name="studentId" required></div>':''}<div class="formrow"><label class="fieldlabel" for="email">Email trường (.edu.vn)</label><input class="field" type="email" id="email" name="email" required></div><div class="formrow"><label class="fieldlabel" for="password">Mật khẩu</label><input class="field" type="password" id="password" name="password" required minlength="8"></div>${err}<button class="btn block">${authTab==='login'?'Đăng nhập':'Tạo tài khoản'}</button></form><p class="hint">Dùng thử: minhanh@student.edu.vn / Rentie123!<br>Tài khoản chỉ lưu trên máy này. Hãy dùng mật khẩu mẫu.</p></div></div>`;return `<div class="container section"><div class="pagehead"><h1>Tài khoản của bạn</h1><p class="muted">Một hồ sơ rõ ràng để chia sẻ đồ dùng an tâm hơn.</p></div><div class="accountlayout"><aside class="surface accountprofile"><span class="avatar">${esc(initials(u.name))}</span><h2>${esc(u.name)}</h2><p class="muted small">${esc(u.studentId||u.role)}</p>${u.role==='student'?`<div class="score">${u.score}<small>/100</small></div><b>Điểm uy tín</b><p class="hint">Bắt đầu từ 100. Mỗi thay đổi đều có đơn thuê đối chiếu.</p>`:''}<button class="btn outline block" data-action="logout">Đăng xuất</button></aside><div><form id="profile-form" class="surface"><h2>Thông tin cá nhân</h2><div class="formrow"><label class="fieldlabel" for="profile-name">Họ tên</label><input class="field" id="profile-name" name="name" value="${esc(u.name)}" required minlength="3" maxlength="80"></div><div class="formrow"><label class="fieldlabel" for="profile-phone">Số điện thoại</label><input class="field" id="profile-phone" name="phone" value="${esc(u.phone)}" pattern="[0-9+ ()-]{9,15}"></div><p class="small muted">${esc(u.email)}</p>${err}<button class="btn">Lưu thông tin</button></form>${u.role==='student'?`<section class="surface mt"><h2>Lịch sử uy tín</h2>${db.reputation.filter(x=>x.user===u.id).map(x=>`<div class="activity"><b>${x.delta>=0?'+':''}${x.delta}</b><div>${esc(x.reason)}<p class="small muted">${x.bookingId} · ${date(x.at)} · ${x.before} → ${x.after}</p></div></div>`).join('')||'<p class="muted small">Chưa có thay đổi uy tín.</p>'}</section><section class="mt"><h2>Đồ đã lưu</h2><div class="productgrid">${db.items.filter(i=>(db.favorites?.[u.id]||[]).includes(i.id)).map(productCard).join('')||'<p class="muted">Chạm biểu tượng trái tim để lưu một vật phẩm.</p>'}</div></section>`:''}<div class="notice mt"><b>Dữ liệu trình diễn</b><p class="small">Khôi phục sẽ xóa tài khoản và thao tác đã thử trên trình duyệt này.</p><button class="btn outline small" data-action="reset">Khôi phục dữ liệu mẫu</button></div></div></div></div>`;}
function guide(){return `<div class="container section"><div class="pagehead"><span class="eyebrow">THUÊ ÍT HƠN. DÙNG NHIỀU HƠN.</span><h1>Mượn một món đồ.<br>Làm thêm một điều hay.</h1><p class="muted">Rentie kết nối sinh viên cho thuê đồ dùng trong khuôn viên trường.</p></div><div class="two-paths"><article class="path"><h2>Tự giao nhận P2P</h2><ol><li>Chọn đồ và thời gian, thanh toán tiền thuê cùng cọc.</li><li>Hai sinh viên tự hẹn địa điểm trong trường.</li><li>Cả hai đối chiếu mã đồ, phụ kiện và lưu ảnh giao nhận.</li><li>Chủ đồ ghi nhận trả; người thuê xác nhận. Tất toán sau đối soát.</li></ol></article><article class="path"><h2>Nhận tại quầy</h2><ol><li>Chủ đồ gửi yêu cầu và mang đồ đến quầy thư viện.</li><li>Thủ kho kiểm định, kiểm tra chỗ và duyệt nhận ký gửi.</li><li>Người thuê đặt đồ, thanh toán, đến quầy nhận.</li><li>Thủ kho ghi nhận trả, tính phí và tất toán.</li></ol></article></div><section class="surface mt" id="policies"><h2>Quy tắc rõ trước khi thuê</h2><div class="tablewrap"><table class="datatable"><tbody><tr><th>Giá & cọc</th><td>Chủ đồ đặt giá theo giờ hoặc ngày, tiền cọc và điểm uy tín tối thiểu. Một ngày = 24 giờ; thời lượng lẻ làm tròn lên.</td></tr><tr><th>Ví Rentie</th><td>Tiền thuê được thanh toán; cọc tạm giữ riêng. Bản này dùng tiền mô phỏng.</td></tr><tr><th>Phí vận hành</th><td>${db.policies.fee}% tiền thuê, khấu trừ khi trả thu nhập cho chủ đồ.</td></tr><tr><th>Trả trễ</th><td>Giá thuê × số giờ/ngày trễ làm tròn lên. Ví dụ giá 25.000đ/giờ, trễ 65 phút: 50.000đ.</td></tr><tr><th>Hư hỏng / mất</th><td>Ghi nhận bằng chứng và chi phí bồi thường. Hệ thống cộng phí, trừ tối đa số cọc; phần vượt cọc được ghi là công nợ.</td></tr><tr><th>Uy tín</th><td>Khởi đầu 100, giới hạn 0–100. Hoàn tất tốt +2; trễ −5; hỏng −10; mất −20. Trễ và hỏng/mất có thể cộng dồn. Chỉ ghi một lần khi tất toán.</td></tr><tr><th>Khiếu nại</th><td>Gửi trong thời gian thuê hoặc sau nhận trả, trước khi tất toán. Thủ kho xử lý nhẹ (≤200.000đ, ≤30% cọc, không mất đồ, bằng chứng thống nhất); Admin xử lý các trường hợp khác.</td></tr><tr><th>Ký gửi</th><td>Mỗi đợt 30 ngày, có thể gia hạn. Quầy giữ cả số chỗ và dung tích cho đồ đang thuê. Nhận lại sau khi kết thúc các đơn; có thể mở đợt ký gửi mới.</td></tr></tbody></table></div></section><div class="notice"><h3>Về bản trình diễn</h3><p>Ảnh sản phẩm là ảnh minh họa. Tin P2P được duyệt nội dung; chỉ đồ ký gửi có bước kiểm định tại quầy. Chọn vai trò ở đầu trang để thử từng quy trình.</p><a class="textlink" href="sitemap.html">Xem toàn bộ 15 màn hình</a></div></div>`;}
function sitemap(){return `<div class="container section"><div class="pagehead"><h1>Một vòng quanh Rentie.</h1><p class="muted">15 màn hình, chia theo việc bạn cần làm.</p></div><div class="sitemapgrid">${Object.entries(titles).map(([k,v])=>`<a class="surface flex between" href="${k==='home'?'index':k}.html"><h3>${v}</h3>${icon('arrow-up-right')}</a>`).join('')}</div></div>`;}
function scan(){const no=requireRole('student','staff');if(no)return `<div class="container section">${no}</div>`;return `<div class="scanpage"><div class="scanwrap"><div class="scanhead"><a class="iconbtn" href="orders.html" aria-label="Về đơn thuê">${icon('arrow-left')}</a><b>Giao nhận Rentie</b><span class="small muted">${scanStage==='scan'?'1 / 3':scanStage==='review'?'2 / 3':'3 / 3'}</span></div>${scanStage==='scan'?`<h1>Quét đúng đồ.<br>Nhận thật yên tâm.</h1><p class="muted small">Quét mã đơn, sau đó mã dán trên vật phẩm.</p><div class="scanner"><video id="camera-video" playsinline muted></video><div class="scanframe"></div><div class="scanplaceholder">${icon('scan-line')}<span id="camera-status">Đưa mã QR vào trong khung</span></div></div><div class="scanbuttons"><button class="btn block" data-action="camera">${icon('camera')}Mở camera</button></div><p class="hint">Camera dùng trên HTTPS hoặc localhost, cần trình duyệt hỗ trợ nhận QR. Bạn luôn có thể nhập mã bên dưới.</p><form id="scan-match" class="surface scanform"><h3>Hoặc nhập mã trên phiếu</h3><div class="formrow"><label class="fieldlabel" for="scan-order">Mã đơn thuê</label><input class="field mono" id="scan-order" name="order" required value="${esc(params.get('order')||'')}" placeholder="RT1001" autocapitalize="characters"></div><div class="formrow"><label class="fieldlabel" for="scan-item">Mã vật phẩm</label><input class="field mono" id="scan-item" name="itemCode" required placeholder="VP1001" autocapitalize="characters"></div><div class="formrow"><label class="fieldlabel" for="scan-mode">Thao tác</label><select class="field" id="scan-mode" name="mode"><option value="handover">Bàn giao cho người thuê</option><option value="return" ${params.get('mode')==='return'?'selected':''}>Nhận trả vật phẩm</option></select></div>${err}<button class="btn block">Đối chiếu mã ${icon('arrow-right')}</button></form>`:scanStage==='review'?scanReview():scanReceipt()}</div></div>`;}
function scanReview(){const b=R.booking(db,scanMatched.order),i=item(b.itemId);return `<h1>Kiểm tra trước<br>khi xác nhận.</h1><div class="surface"><div class="flex">${photo(i,'miniphoto')}<div><h3>${esc(i.name)}</h3><span class="mono small">${b.id} / ${i.id}</span></div></div><p class="notice small">Mã vật phẩm khớp đơn thuê.</p><p class="small"><b>Phụ kiện:</b> ${esc(i.accessories)}</p><p class="small"><b>Người thuê:</b> ${esc(R.user(db,b.renter).name)}</p><p class="small"><b>Hạn trả:</b> ${date(b.end)}</p></div><form id="scan-confirm" class="surface mt">${scanMatched.mode==='return'?`<div class="formrow"><label class="fieldlabel" for="return-at">Thời điểm trả thực tế</label><input class="field" id="return-at" type="datetime-local" name="at" value="${stamp()}" required></div><div class="formrow"><label class="fieldlabel" for="return-type">Hiện trạng</label><select class="field" id="return-type" name="type"><option value="good">Đầy đủ, hoạt động tốt</option><option value="damage">Có hư hỏng</option><option value="lost">Mất vật phẩm</option></select></div><div class="formrow"><label class="fieldlabel" for="damage">Chi phí bồi thường có bằng chứng (đ)</label><input class="field" id="damage" type="number" name="damage" min="0" value="0" required></div><div class="formrow"><label class="fieldlabel" for="return-note">Ghi nhận</label><textarea class="field" id="return-note" name="note" maxlength="500"></textarea></div>`:''}${evidenceField('scan-evidence')}<label class="small flex mt"><input type="checkbox" required> Tôi đã đối chiếu đúng đồ, phụ kiện và ảnh hiện trạng.</label>${err}<div class="stickyaction"><button class="btn block">Xác nhận ${scanMatched.mode==='return'?'nhận trả':'bàn giao'} ${icon('check')}</button><button class="btn ghost block" type="button" data-action="scan-back">Quay lại kiểm tra mã</button></div></form>`;}
function scanReceipt(){const b=R.booking(db,scanMatched.order);return `<div class="scanreceipt"><div class="successcircle">${icon('check')}</div><h1>Đã lưu xác nhận.</h1><p class="muted">${b.status==='booked'||b.status==='active'&&b.returnBy.length?'Đang chờ bên còn lại đối chiếu và xác nhận.':'Hồ sơ giao nhận đã được cập nhật.'}</p><div class="surface"><div class="summary"><div><span>Mã đơn</span><b>${b.id}</b></div><div><span>Vật phẩm</span><b>${esc(item(b.itemId).name)}</b></div><div><span>Trạng thái</span>${badge(b.status)}</div></div></div><a class="btn block mt" href="orders.html">Xem đơn thuê</a><button class="btn outline block mt" data-action="scan-back">Quét mã khác</button></div>`;}
function stopCamera(){if(scanControls){scanControls.getTracks().forEach(t=>t.stop());scanControls=null;}}
async function camera(){try{if(!window.isSecureContext)throw Error('Hãy dùng HTTPS hoặc localhost để mở camera.');if(!('BarcodeDetector' in window))throw Error('Trình duyệt chưa hỗ trợ đọc QR trực tiếp. Hãy nhập mã trên phiếu bên dưới.');const formats=await BarcodeDetector.getSupportedFormats();if(!formats.includes('qr_code'))throw Error('Thiết bị chưa hỗ trợ đọc QR. Bạn có thể nhập mã bên dưới.');stopCamera();scanControls=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});const video=$('#camera-video');video.srcObject=scanControls;await video.play();$('.scanner').classList.add('live');const detector=new BarcodeDetector({formats:['qr_code']});const tick=async()=>{if(!scanControls||!document.contains(video))return;try{const codes=await detector.detect(video);for(const c of codes){const s=c.rawValue.trim().toUpperCase();if(/^RT\d{4,12}$/.test(s)){$('#scan-order').value=s;$('#camera-status').textContent='Đã đọc mã đơn. Tiếp tục quét mã vật phẩm.';}else if(/^VP\d{4,12}$/.test(s)){$('#scan-item').value=s;$('#camera-status').textContent='Đã đọc mã vật phẩm. Nhấn Đối chiếu mã.';}}}catch{}setTimeout(tick,400);};tick();}catch(e){stopCamera();toast(e.message||'Không mở được camera. Hãy cấp quyền hoặc nhập mã bên dưới.');}}
function render(){stopCamera();const f={home,catalog,item:detail,publish:publishPage,dashboard,orders,wallet,inventory,warehouse,admin,disputes,account,guide,sitemap,scan};const content=(f[page]||home)();$('#app').innerHTML=header()+(panelPages.includes(page)?`<div class="dashshell">${sidebar()}<main id="main" class="dashmain">${content}</main></div>`:`<main id="main">${content}</main>${page==='scan'?'':footer()}`)+mobilebar();icons();if(page==='item')updateQuote();}
function formData(form){return Object.fromEntries(new FormData(form));}
function evidence(form){const value=$('[name=evidence]',form)?.value;if(!value)throw Error('Thêm ảnh hiện trạng hoặc dùng ảnh mẫu để thử.');return JSON.parse(value);}
function summarySettlement(b){const q=R.settlement(b);return `<div class="summary">${[['Tiền thuê',b.fee],['Phí vận hành',q.operation],['Phí trễ ('+q.lateUnits+' '+unit(b)+')',q.late],['Bồi thường hiện trạng',q.damage],['Tổng phạt sau xử lý',q.penalty],['Cọc hoàn người thuê',q.refund],['Thu nhập thuê chủ đồ',q.income],['Bồi thường trả chủ đồ',q.compensation],['Công nợ còn lại',q.debt]].map(([l,v])=>`<div><span>${l}</span><b>${V(v)}</b></div>`).join('')}</div>`;}
function confirmDialog(title,text,fn){modal(title,`<p>${text}</p>${err}<div class="actionrow"><button class="btn" id="confirm-action">Xác nhận</button><button class="btn outline" data-action="close">Quay lại</button></div>`);$('#confirm-action').onclick=()=>act(fn,'Đã cập nhật.');}
function orderDetail(id){const b=R.booking(db,id),i=item(b.itemId);modal('Đơn thuê '+id,`${photo(i)}<h3 class="mt">${esc(i.name)}</h3>${badge(b.status,b.status==='pending'?'Chờ thanh toán':null)}<p class="small">${date(b.start)} → ${date(b.end)}<br>${esc(b.location)}</p><p class="small">Người thuê: ${esc(R.user(db,b.renter).name)}<br>Chủ đồ: ${esc(R.user(db,b.owner).name)}</p>${b.returnAt?summarySettlement(b):`<p>Tiền thuê <b>${V(b.fee)}</b> · Cọc <b>${V(b.deposit)}</b></p>`}<h3>Hồ sơ hiện trạng</h3>${db.inspections.filter(x=>x.bookingId===id).map(x=>`<div class="activity">${proof(x.evidence)}<div class="small">${x.stage==='return'?'Nhận trả':'Bàn giao'} · ${esc(R.user(db,x.by).name)}<p>${date(x.at)}</p>${esc(x.note)}</div></div>`).join('')||'<p class="small muted">Chưa có ảnh giao nhận.</p>'}<div class="actionrow">${orderButtons(b).replace(/<button[^>]*data-action="order-detail"[^>]*>.*?<\/button>/,'')}</div>`);}
document.addEventListener('click',e=>{const t=e.target.closest('[data-action]');if(!t)return;const a=t.dataset.action,id=t.dataset.id;try{
if(a==='close')closeModal();else if(a==='theme'){document.documentElement.classList.toggle('dark');document.documentElement.dataset.theme=document.documentElement.classList.contains('dark')?'dark':'light';localStorage.setItem('rentie-theme',document.documentElement.classList.contains('dark')?'dark':'light');}else if(a==='menu'){const nav=$('.navlinks');nav.classList.toggle('open');t.setAttribute('aria-expanded',nav.classList.contains('open'));}else if(a==='category'){filters.category=t.dataset.category||'';if(page==='home')location.href='catalog.html?category='+encodeURIComponent(filters.category);else render();}else if(a==='order-tab'){orderTab=t.dataset.tab;render();}else if(a==='admin-tab'){adminTab=t.dataset.tab;render();}else if(a==='auth-tab'){authTab=t.dataset.tab;render();}else if(a==='favorite'){if(!me())throw Error('Đăng nhập để lưu vật phẩm.');act(n=>{n.favorites??={};const f=n.favorites[n.activeUser]??=[];n.favorites[n.activeUser]=f.includes(id)?f.filter(v=>v!==id):[...f,id];},'Đã cập nhật đồ đã lưu.');}else if(a==='order-detail')orderDetail(id);else if(a==='qr'||a==='item-qr')modal(a==='qr'?'Mã đơn thuê':'Mã vật phẩm',`<div class="qrbox">${RentieQR.svg(id)}<h2 class="mono">${esc(id)}</h2><p class="small muted">${a==='qr'?'Quét mã này, rồi mã dán trên vật phẩm.':'Dán hoặc đối chiếu mã này trên đúng vật phẩm.'}</p></div>`);else if(a==='pay'){const b=R.booking(db,id);confirmDialog('Thanh toán bằng ví Rentie',`Tiền thuê: <b>${V(b.fee)}</b><br>Cọc tạm giữ: <b>${V(b.deposit)}</b><br>Tổng trừ khả dụng: <b>${V(b.fee+b.deposit)}</b><br><span class="hint">Giao dịch mô phỏng.</span>`,n=>R.pay(n,id));}else if(a==='cancel')confirmDialog('Hủy đơn thuê','Tiền thuê và cọc đã thanh toán sẽ được hoàn về ví mô phỏng.',n=>R.cancel(n,id));else if(a==='toggle-item')act(n=>R.toggleItem(n,id),'Đã đổi trạng thái tin.');else if(a==='consignment')confirmDialog('Cập nhật đợt ký gửi',({renew:'Gia hạn lưu ký thêm 30 ngày.',request:'Ẩn tin và yêu cầu nhận lại đồ tại quầy.',return:'Xác nhận đã đối chiếu và trả đúng đồ cho chủ sở hữu.',resubmit:'Mở đợt ký gửi mới và chờ kiểm định.'})[t.dataset.type],n=>R.consignment(n,id,t.dataset.type));else if(a==='transfer')modal(t.dataset.type==='topup'?'Nạp tiền mô phỏng':'Rút tiền mô phỏng',`<form id="transfer-form"><input type="hidden" name="type" value="${t.dataset.type}"><label class="fieldlabel" for="amount">Số tiền (đ)</label><input class="field" id="amount" name="amount" type="number" min="10000" max="10000000" step="1000" value="500000" required><p class="hint">Không kết nối ngân hàng và không giao dịch tiền thật.</p>${err}<button class="btn block">Xác nhận</button></form>`);else if(a==='settle'){const b=R.booking(db,id);modal('Đối soát và tất toán '+id,`<form id="settle-form"><input type="hidden" name="id" value="${id}">${summarySettlement(b)}<label class="flex small mt"><input type="checkbox" required> Hai bên đã đối chiếu; không còn tranh chấp.</label><p class="hint">Tất toán sẽ hoàn cọc, trả thu nhập và cập nhật uy tín một lần.</p>${err}<button class="btn block">Hoàn tất tất toán</button></form>`);}else if(a==='complain')modal('Gửi khiếu nại',`<form id="dispute-form"><input type="hidden" name="id" value="${id}"><div class="formrow"><label class="fieldlabel" for="reason">Nội dung</label><textarea class="field" id="reason" name="reason" required minlength="10" maxlength="1000"></textarea></div><div class="formrow"><label class="fieldlabel" for="dispute-amount">Giá trị tranh chấp (đ)</label><input class="field" id="dispute-amount" name="amount" type="number" min="0" value="0" required></div><label class="flex small"><input type="checkbox" name="lost"> Có mất vật phẩm</label><label class="flex small mt"><input type="checkbox" name="disagree"> Hai bên chưa thống nhất bằng chứng</label>${evidenceField()}${err}<button class="btn block mt">Gửi hồ sơ</button></form>`);else if(a==='resolve'){const d=db.disputes.find(x=>x.id===id),b=R.booking(db,d.bookingId);modal('Xử lý '+id,`<form id="resolve-form"><input type="hidden" name="id" value="${id}"><p>${esc(d.reason)}</p><label class="fieldlabel" for="decision">Kết luận / lý do chuyển cấp</label><textarea class="field" id="decision" name="decision" required minlength="10"></textarea><label class="fieldlabel mt" for="penalty">Tổng phạt sau xử lý (đ)</label><input class="field" id="penalty" name="penalty" type="number" min="0" value="${b.returnAt?R.settlement(b).penalty:0}" required><p class="hint">Điều chỉnh tổng phạt khi đã có biên bản trả. Uy tín vẫn theo hiện trạng đã ghi nhận.</p>${me().role==='staff'?'<label class="flex small"><input name="escalate" type="checkbox"> Chuyển Admin xử lý</label>':''}${err}<button class="btn block mt">Lưu kết luận</button></form>`);}else if(a==='confirm-return'){const b=R.booking(db,id);modal('Đối chiếu hiện trạng trả',`<form id="confirm-return-form"><input type="hidden" name="id" value="${id}">${summarySettlement(b)}<p class="small">${b.returnType==='good'?'Đồ tốt, đủ phụ kiện':b.returnType==='damage'?'Có hư hỏng':'Mất vật phẩm'} · Trả lúc ${date(b.returnAt)}</p>${db.inspections.filter(x=>x.bookingId===id&&x.stage==='return').map(x=>proof(x.evidence)).join('')}${evidenceField()}<label class="flex small mt"><input type="checkbox" required> Tôi đồng ý hiện trạng và khoản phí nêu trên.</label>${err}<button class="btn block mt">Xác nhận trả đồ</button></form>`);}else if(a==='approve'||a==='reject'){const i=item(id);modal(a==='approve'?'Xét duyệt vật phẩm':'Từ chối vật phẩm',`<form id="approve-form"><input type="hidden" name="id" value="${id}"><input type="hidden" name="accepted" value="${a==='approve'}"><h3>${esc(i.name)}</h3><p class="small">${esc(i.accessories)} · ${i.volume} L</p>${a==='reject'?'<label class="fieldlabel" for="reject-reason">Lý do từ chối</label><textarea class="field" id="reject-reason" name="reason" required></textarea>':i.mode==='counter'?evidenceField()+'<label class="flex small mt"><input type="checkbox" required> Đã kiểm tra hoạt động, phụ kiện và dung tích.</label>':'<p class="notice small">Duyệt nội dung tin P2P. Không xác nhận đã kiểm định vật phẩm trực tiếp.</p>'}${err}<button class="btn block mt">${a==='approve'?'Duyệt vật phẩm':'Lưu lý do từ chối'}</button></form>`);}else if(a==='lock-user')confirmDialog('Đổi trạng thái tài khoản','Tài khoản bị khóa không thể thao tác. Hồ sơ và giao dịch vẫn được lưu.',n=>{R.role(n,'admin');const u=R.user(n,id);if(u.role!=='student')throw Error('Chỉ áp dụng tài khoản sinh viên.');u.status=u.status==='active'?'locked':'active';});else if(a==='rename-category')modal('Đổi tên danh mục',`<form id="rename-category-form"><input type="hidden" name="oldName" value="${esc(t.dataset.name)}"><label class="fieldlabel" for="new-category">Tên danh mục</label><input class="field" id="new-category" name="name" required maxlength="40" value="${esc(t.dataset.name)}">${err}<button class="btn block mt">Lưu tên</button></form>`);else if(a==='hide-category')act(n=>{R.role(n,'admin');n.hiddenCategories??=[];const name=t.dataset.name;n.hiddenCategories=n.hiddenCategories.includes(name)?n.hiddenCategories.filter(c=>c!==name):[...n.hiddenCategories,name];},'Đã cập nhật danh mục.');else if(a==='delete-category')confirmDialog('Xóa danh mục',`Xóa danh mục ${esc(t.dataset.name)} nếu chưa được vật phẩm sử dụng.`,n=>{R.role(n,'admin');if(n.items.some(i=>i.category===t.dataset.name))throw Error('Danh mục đang được vật phẩm sử dụng.');n.categories=n.categories.filter(c=>c!==t.dataset.name);});else if(a==='logout')act(n=>{n.activeUser=null;},'Đã đăng xuất.','account.html');else if(a==='reset')confirmDialog('Khôi phục dữ liệu mẫu','Toàn bộ thao tác và tài khoản tự tạo trong bản demo này sẽ bị xóa.',n=>{Object.keys(n).forEach(k=>delete n[k]);Object.assign(n,R.seed());});else if(a==='scan-back'){scanStage='scan';scanMatched=null;render();}else if(a==='camera')camera();else if(a==='sample-evidence'){const field=t.closest('.evidencefield'),p=scanMatched?item(R.booking(db,scanMatched.order).itemId).photo:0;const value={sample:true,photo:p};$('[name=evidence]',field).value=JSON.stringify(value);$('.evidencepreview',field).innerHTML=proof(value);toast('Đã chọn ảnh mẫu cho bản trình diễn.');}
}catch(ex){toast(ex.message);}});
document.addEventListener('submit',e=>{const f=e.target,fid=f.getAttribute('id');if(!fid)return;e.preventDefault();const d=formData(f);try{
if(fid==='search-form'){filters.q=d.q||'';if(page==='home')location.href='catalog.html?q='+encodeURIComponent(filters.q);else render();}else if(fid==='booking-form')act(n=>R.createBooking(n,{...d,start:toISO(d.start),end:toISO(d.end)}),'','orders.html');else if(fid==='transfer-form')act(n=>R.transfer(n,d.amount,d.type),'Ví đã được cập nhật.');else if(fid==='publish-form')act(n=>R.publish(n,{...d,appointmentAt:d.appointmentAt?toISO(d.appointmentAt):null},d.id||undefined),'','inventory.html');else if(fid==='settle-form')act(n=>R.settle(n,d.id),'Đã tất toán và cập nhật ví, uy tín.');else if(fid==='dispute-form'){d.evidence=evidence(f);act(n=>R.openDispute(n,d.id,d),'','disputes.html');}else if(fid==='resolve-form')act(n=>R.resolveDispute(n,d.id,d),'Đã cập nhật hồ sơ.');else if(fid==='confirm-return-form'){const ev=evidence(f);act(n=>R.confirmReturn(n,d.id,ev),'Đã xác nhận hiện trạng trả.');}else if(fid==='approve-form'){const accepted=d.accepted==='true',i=item(d.id),ev=accepted&&i.mode==='counter'?evidence(f):null;act(n=>{const result=R.approve(n,d.id,accepted,d.reason);if(ev)n.inspections.unshift({id:'KT'+(++n.sequence),itemId:d.id,consignmentId:n.consignments.find(c=>c.itemId===d.id&&c.status==='active')?.id,stage:'intake',by:n.activeUser,evidence:ev,note:'Kiểm định nhận ký gửi',at:new Date().toISOString()});return result;},'Đã lưu kết quả xét duyệt.');}else if(fid==='rename-category-form')act(n=>{R.role(n,'admin');const name=d.name.trim();if(!name||n.categories.some(c=>c!==d.oldName&&c.toLowerCase()===name.toLowerCase()))throw Error('Tên trống hoặc danh mục đã tồn tại.');n.categories=n.categories.map(c=>c===d.oldName?name:c);n.items.forEach(i=>{if(i.category===d.oldName)i.category=name;});n.hiddenCategories=(n.hiddenCategories||[]).map(c=>c===d.oldName?name:c);},'Đã đổi tên danh mục.');else if(fid==='category-form')act(n=>{R.role(n,'admin');const name=d.name.trim();if(!name||n.categories.some(c=>c.toLowerCase()===name.toLowerCase()))throw Error('Tên trống hoặc danh mục đã tồn tại.');n.categories.push(name);},'Đã thêm danh mục.');else if(fid==='settings-form')act(n=>{R.role(n,'admin');const c=R.capacity(n);if(+d.maxCount<c.count||+d.maxVolume<c.volume)throw Error('Sức chứa không được thấp hơn phần đang giữ chỗ.');n.policies={fee:+d.fee,maxCount:+d.maxCount,maxVolume:+d.maxVolume};},'Đã lưu cấu hình.');else if(fid==='profile-form')act(n=>{Object.assign(R.actor(n),{name:d.name.trim(),phone:d.phone});},'Đã lưu hồ sơ.');else if(fid==='auth-form')act(n=>{const email=d.email.trim().toLowerCase();if(d.type==='login'){const u=n.users.find(u=>u.email.toLowerCase()===email&&u.password===d.password);if(!u||u.status!=='active')throw Error('Email, mật khẩu chưa đúng hoặc tài khoản đã bị khóa.');n.activeUser=u.id;}else{if(!/^[^@\s]+@[^@\s]+\.edu\.vn$/.test(email))throw Error('Dùng địa chỉ email của trường kết thúc bằng .edu.vn.');if(n.users.some(u=>u.email===email||u.studentId===d.studentId.trim()))throw Error('Email hoặc mã sinh viên đã được đăng ký.');const u={id:'SV'+(++n.sequence),name:d.name.trim(),studentId:d.studentId.trim(),email,password:d.password,phone:'',role:'student',status:'active',score:100,balance:0,held:0};n.users.push(u);n.activeUser=u.id;}},'','dashboard.html');else if(fid==='scan-match'){const b=R.booking(db,d.order.trim().toUpperCase());if(b.itemId!==d.itemCode.trim().toUpperCase())throw Error('Mã vật phẩm không khớp đơn. Hãy đối chiếu lại nhãn.');if((d.mode==='handover'&&b.status!=='booked')||(d.mode==='return'&&b.status!=='active'))throw Error('Trạng thái đơn chưa phù hợp với thao tác đã chọn.');const u=R.actor(db);if(b.mode==='counter'?u.role!=='staff':d.mode==='return'?u.id!==b.owner:![b.owner,b.renter].includes(u.id))throw Error('Vai trò hiện tại không có quyền thực hiện giao nhận này.');scanMatched={order:b.id,itemCode:b.itemId,mode:d.mode};scanStage='review';render();window.scrollTo(0,0);}else if(fid==='scan-confirm'){const ev=evidence(f),next=JSON.parse(JSON.stringify(db));if(scanMatched.mode==='handover')R.handover(next,scanMatched.order,scanMatched.itemCode,ev);else R.returnItem(next,scanMatched.order,{...d,at:toISO(d.at),itemCode:scanMatched.itemCode,evidence:ev});save(next);scanStage='receipt';render();window.scrollTo(0,0);}
}catch(ex){const target=$('.form-error',f);if(target){target.textContent=ex.message;target.hidden=false;target.scrollIntoView({block:'nearest'});}else toast(ex.message);}});
document.addEventListener('change',async e=>{const t=e.target;if(t.id==='demo-user'){act(n=>{n.activeUser=t.value;},'Đã chuyển tài khoản trình diễn.');scanStage='scan';scanMatched=null;if(page==='scan')render();}else if(t.id==='filter-mode'){filters.mode=t.value;render();}else if(t.id==='filter-sort'){filters.sort=t.value;render();}else if(t.closest('#booking-form'))updateQuote();else if(t.type==='file'&&t.files[0]){try{const file=t.files[0];if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024)throw Error('Chọn ảnh JPG, PNG hoặc WebP tối đa 8 MB.');const src=await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=no;r.readAsDataURL(file);});const img=await new Promise((ok,no)=>{const i=new Image();i.onload=()=>ok(i);i.onerror=no;i.src=src;});const ratio=Math.min(1,1000/img.width,1000/img.height),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*ratio);canvas.height=Math.round(img.height*ratio);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/jpeg',.75);if(t.name==='itemImage')$('[name=image]',t.form).value=data;else{const field=t.closest('.evidencefield'),ev={src:data,sample:false};$('[name=evidence]',field).value=JSON.stringify(ev);$('.evidencepreview',field).innerHTML=proof(ev);}toast('Đã thêm ảnh.');}catch(ex){t.value='';toast(ex.message||'Không đọc được ảnh.');}}});
window.addEventListener('pagehide',stopCamera);
try{if(localStorage.getItem('rentie-theme')==='dark'){document.documentElement.classList.add('dark');document.documentElement.dataset.theme='dark';}}catch{}
filters.mode=params.get('mode')||'';
render();
})();


